package collaboration

import (
	_ "embed"
	"encoding/json"
)

// Generated by apps/collaboration's documentFromProjection/encodeSnapshot.
// The engine test decodes and validates this exact artifact. Never edit Yjs
// bytes by hand or use this seed to replace an existing document.
//
//go:embed empty-document-seed.json
var emptyDocumentSeedArtifact []byte

// NewEmptyDocumentSeed supplies an attested initial CRDT for a newly inserted
// blank document. The caller must create its source, policy, seed and mode marker
// in one transaction; this is not an existing-document cutover operation.
func NewEmptyDocumentSeed(room Room, actorID uint, policyRevision uint64, sourceHash string) (DocumentSeed, error) {
	var artifact struct {
		Version         int             `json:"version"`
		Snapshot        []byte          `json:"snapshot"`
		SnapshotHash    string          `json:"snapshot_hash"`
		StateVector     []byte          `json:"state_vector"`
		StateVectorHash string          `json:"state_vector_hash"`
		Projection      json.RawMessage `json:"projection"`
		ProjectionHash  string          `json:"projection_hash"`
	}
	if json.Unmarshal(emptyDocumentSeedArtifact, &artifact) != nil || artifact.Version != 1 {
		return DocumentSeed{}, ErrDataCorrupt
	}
	seed := DocumentSeed{
		Room: room, ActorUserID: actorID, PolicyRevision: policyRevision,
		SourceRevision: 1, SourceHash: sourceHash,
		Snapshot: artifact.Snapshot, SnapshotHash: artifact.SnapshotHash,
		StateVector: artifact.StateVector, StateVectorHash: artifact.StateVectorHash,
		Projection: artifact.Projection, ProjectionHash: artifact.ProjectionHash,
	}
	if err := ValidateDocumentSeed(seed); err != nil {
		return DocumentSeed{}, err
	}
	return seed, nil
}
